import { listBuckets, removeBucket } from "@tigrisdata/storage";
import { createForks, teardownForks } from "@tigrisdata/agent-kit";
import { writeFileSync } from "fs";

async function main() {
  const sourceBucket = "source-bucket";
  const prefix = "eval-prefix";
  const forkCount = 3;
  const outputFile = "/home/user/safe-fork/forks.json";

  console.log("Detecting prefix collisions...");
  // Credentials are picked up from environment variables automatically
  const { data: bucketsData, error: listError } = await listBuckets();
  if (listError) {
    console.error("Error listing buckets:", listError);
    process.exit(1);
  }

  const buckets = bucketsData?.buckets || [];
  const collidingBuckets = buckets.filter(b => b.name.startsWith(prefix));
  console.log(`Found ${collidingBuckets.length} colliding buckets.`);

  for (const bucket of collidingBuckets) {
    console.log(`Deleting colliding bucket: ${bucket.name}`);
    const { error: deleteError } = await removeBucket(bucket.name, { force: true });
    if (deleteError) {
      console.error(`Error deleting bucket ${bucket.name}:`, deleteError);
      process.exit(1);
    }
  }

  console.log(`Creating ${forkCount} forks for ${sourceBucket}...`);
  const { data: forkSet, error: forkError } = await createForks(sourceBucket, forkCount, {
    prefix: prefix,
    credentials: { role: "Editor" }
  });

  if (forkError) {
    console.error("Error creating forks:", forkError);
    process.exit(1);
  }

  if (!forkSet || forkSet.forks.length !== forkCount) {
    console.error(`Expected ${forkCount} forks, but got ${forkSet?.forks?.length}`);
    process.exit(1);
  }

  const forkNames = forkSet.forks.map(f => f.bucket);
  console.log("Created forks:", forkNames);

  const output = {
    forks: forkNames
  };

  writeFileSync(outputFile, JSON.stringify(output));
  console.log(`Fork names written to ${outputFile}`);

  console.log("Tearing down forks...");
  const { error: teardownError } = await teardownForks(forkSet);
  if (teardownError) {
    console.error("Error tearing down forks:", teardownError);
    process.exit(1);
  }

  console.log("Success!");
  process.exit(0);
}

main().catch(err => {
  console.error("Unhandled error:", err);
  process.exit(1);
});
